def f(x) {
    return x / 0
}
f(3)

try { print(1)
print(1 / 0)
print(2) } catch e { print("caught") }

def boom() { return 1 / 0 }
def middle() { return boom() }
try { middle() } catch e { print("caught", e) }

let trail = []
def risky(n) { if n > 1 { throw("too big: " + str(n)) }
append(trail, n) }
for i = 0 to 2 { try { risky(i) } catch e { append(trail, e) } finally { append(trail, "done") } }
print(trail)
